<div class="page-head"><div><h1>Πελάτες</h1></div></div>
<div class="card"><form class="toolbar" method="get"><input type="search" name="q" value="<?= e(in_str('q')) ?>" placeholder="Email, όνομα, τηλέφωνο" aria-label="Αναζήτηση"><button class="btn">Αναζήτηση</button></form>
<div class="table-wrap"><?php if (!$rows): ?><div class="empty">Δεν υπάρχουν πελάτες ακόμη.</div><?php else: ?><table class="table"><thead><tr><th>Πελάτης</th><th>Λογαριασμός</th><th class="r">Παραγγελίες</th><th class="r">Αξία</th><th>Εγγραφή</th></tr></thead><tbody>
<?php foreach ($rows as $c): ?><tr><td><a class="title" href="/admin/customers/<?= $c['id'] ?>"><?= e(trim($c['first_name'] . ' ' . $c['last_name']) ?: $c['email']) ?></a><div class="sub"><?= e($c['email']) ?> · <?= e($c['phone']) ?></div></td><td><?= $c['password_hash'] ? '<span class="badge b-ok">Λογαριασμός</span>' : '<span class="badge b-muted">Επισκέπτης</span>' ?><?= $c['marketing_consent'] ? ' <span class="badge b-info plain">newsletter</span>' : '' ?></td><td class="r num"><?= (int) $c['orders'] ?></td><td class="r num"><?= money((float) $c['spent']) ?></td><td class="num"><?= fmt_date($c['created_at']) ?></td></tr><?php endforeach; ?>
</tbody></table><?php endif; ?></div><?php include __DIR__ . '/_pager.php'; ?></div>
